import { describe, expect, it } from 'vitest'

import { highlightCode } from './highlight-code'

const MODULE = [
  '// Generated by nudo-tsl from a node graph.',
  "import { color, float } from 'three/tsl'",
  '',
  'const color1 = color(0xff7c3f)',
  'export const nodes = {',
  '  roughnessNode: color1.mul(float(0.5)),',
  '}',
].join('\n')

const textOf = (line: readonly { readonly text: string }[]): string =>
  line.map((token) => token.text).join('')

describe('highlightCode', () => {
  it('keeps every character, one entry per line', () => {
    const lines = highlightCode(MODULE)

    expect(lines).toHaveLength(7)
    expect(lines.map(textOf).join('\n')).toBe(MODULE)
    expect(lines[2]).toEqual([])
  })

  it('reads comments, keywords, strings and numbers as JavaScript', () => {
    const [comment, imports, , constant] = highlightCode(MODULE)

    expect(comment).toEqual([{ kind: 'comment', text: '// Generated by nudo-tsl from a node graph.' }])
    expect(imports?.find((token) => token.text === 'import')?.kind).toBe('keyword')
    expect(imports?.find((token) => token.text === 'three/tsl')?.kind).toBe('string')
    expect(constant?.find((token) => token.text === '0xff7c3f')?.kind).toBe('class')
  })
})
